import {CampaignLevel1} from './campaign-level1.js';
import {ArenaGame,clamp,segmentBox} from './game-logic.js';
import {BREACH,breachTraversal} from './breach-layout.js';
const siteHeight=p=>p.x===15&&p.z===8?4:0;
const titles={arrival:['01 · Arrivée','Rejoindre le hangar. Déplacements, saut et accroupissement libres.'],hangar:['02 · Hangar de transit','Neutraliser les deux sentinelles. Utiliser les containers.'],passages:['03 · Passerelles et tunnels','Choisir la passerelle ou le tunnel puis rejoindre la cour.'],courtyard:['04 · Cour centrale','Neutraliser la patrouille puis activer les deux relais.'],reactor:['05 · Cœur énergétique','Détruire les trois stabilisateurs pour retirer le blindage du gardien.'],extraction:['06 · Extraction','Surcharge engagée. Rejoindre le portail au nord.'],complete:['La Brèche Violette','Complexe neutralisé. Extraction réussie.']};
export class BreachLevel1 extends CampaignLevel1{
 reset(id=this.characterId||'ghju'){ArenaGame.prototype.reset.call(this);this.mode='campaign';this.characterId=id;this.sibling=id==='ghju'?'LYLU':'GHJU';this.stage='arrival';this.relays=[false,false];this.stabilizers=[false,false,false];this.completed=false;this.checkpoint='arrival';this.encounter=0;this.toSpawn=0;this.nextSpawnAt=Infinity;this.traversal=breachTraversal;this.routes=breachTraversal.routes;this.lifts=[];this.stairNavigation=this.routes.map(()=>new this.navigation.constructor(this.obstacles));Object.assign(this.player,{...BREACH.start,elevation:0,yaw:0});this.nextWave=-1;this.secretFound=[false,false];return this;}

 resumeCheckpoint(checkpoint){if(!['passages','reactor'].includes(checkpoint))return;this.enemies=[];this.checkpoint=checkpoint;this.stage=checkpoint;this.ownedWeapons.add(1);if(checkpoint==='passages'){Object.assign(this.player,{x:0,z:34,elevation:0});this.deploy(['synth','seer','stalker'],[{x:15,z:8},{x:-13,z:10},{x:3,z:12}]);}else{Object.assign(this.player,{x:0,z:-30,elevation:0});this.relays=[true,true];this.encounter=2;this.deploy(['bulwark'],[{x:0,z:-55}]);this.enemies[0].guardian=true;this.enemies[0].elite=true;this.enemies[0].hp=700;}this.setStage(checkpoint);}
 get campaign(){const t=titles[this.stage]||titles.arrival;let objective=null;if(this.stage==='courtyard'&&!this.enemies.length){const i=this.relays.findIndex(v=>!v);if(i>=0)objective={id:`relay-${i}`,label:`ACTIVER RELAIS ${i+1}/2`,position:BREACH.relays[i]};}if(this.stage==='reactor'){const i=this.stabilizers.findIndex(v=>!v);if(i>=0)objective={id:`stabilizer-${i}`,label:`SABOTER STABILISATEUR ${i+1}/3`,position:BREACH.stabilizers[i]};}if(this.stage==='extraction')objective={id:'exit',label:'EXTRACTION',position:BREACH.exit};return {id:'breche-violette-01',name:'La Brèche Violette',stage:this.stage,title:t[0],subtitle:t[1],objective,archive:[],sibling:this.sibling,remaining:this.enemies.length,total:13,completed:this.completed,relays:this.relays,stabilizers:this.stabilizers,checkpoint:this.checkpoint,secrets:this.secretFound};}
 getInteraction(){const o=this.campaign.objective;if(this.state!=='playing'||!o)return null;const p=o.position;if(Math.hypot(this.player.x-p.x,this.player.z-p.z)>2.65||Math.abs(this.player.elevation-p.y)>.6)return null;return this.obstacles.some(b=>b.kind!=='terminal'&&!b.walkableSurface&&segmentBox({x:this.player.x,y:this.player.elevation+1.4,z:this.player.z},{x:p.x,y:p.y+1.4,z:p.z},b)!==null)?null:o;}
 interact(){const o=this.getInteraction();if(!o)return false;if(o.id.startsWith('relay')){this.relays[Number(o.id.at(-1))]=true;if(this.relays.every(Boolean)){this.checkpoint='reactor';this.activePortals=[];this.setStage('reactor');this.encounter=2;this.deploy(['bulwark'],[{x:0,z:-55}]);this.enemies[0].guardian=true;this.enemies[0].elite=true;this.enemies[0].hp=700;}}
 else if(o.id.startsWith('stabilizer')){this.stabilizers[Number(o.id.at(-1))]=true;this.event('impact',{x:o.position.x,y:1.5,z:o.position.z,surface:'metal'});}else if(o.id==='exit'){this.completed=true;this.state='won';this.bullets=[];this.setStage('complete');this.event('win',{campaign:true,level:1});}return true;}
 deploy(forms,sites){forms.forEach((form,i)=>{const e=this.makeEnemy(form,{...sites[i%sites.length],id:201+i,yaw:0});if(siteHeight(sites[i%sites.length])>0){e.homeHeight=4;e.elevation=4;}e.speed*=.7;e.awareness='patrol';e.alertedUntil=0;this.enemies.push(e);});}
 event(type,data={}){super.event(type,data);if(type==='impact'&&this.stage==='reactor'&&!data.hostile&&!data.enemy){const i=BREACH.stabilizers.findIndex(p=>Math.abs(p.x-data.x)<.9&&Math.abs(p.z-1.4-data.z)<.75&&data.y<2);if(i>=0){this.stabilizerHits||=[0,0,0];if(++this.stabilizerHits[i]>=4)this.stabilizers[i]=true;}}}
 damageEnemy(e,...args){if(e.guardian&&!this.stabilizers.every(Boolean))return;return super.damageEnemy(e,...args);}
 step(dt,input={}){if(this.state!=='playing')return;this.nextWave=Infinity;this.spawnTimer=Infinity;ArenaGame.prototype.step.call(this,clamp(dt,0,.05),input);this.nextWave=-1;if(this.state!=='playing')return;const p=this.player;
 if(this.stage==='arrival'&&p.z<62){this.setStage('hangar');this.deploy(['synth','seer'],[{x:-8,z:49},{x:10,z:43}]);}
 else if(this.stage==='hangar'&&!this.enemies.length){this.checkpoint='passages';this.offerWeapon(1);this.setStage('passages');this.deploy(['synth','seer','stalker'],[{x:15,z:8},{x:-13,z:10},{x:3,z:12}]);}
 else if(this.stage==='passages'&&p.z<0&&!this.enemies.length){this.setStage('courtyard');this.activePortals=[{id:701,x:0,z:-23,yaw:0,openedAt:this.time}];this.encounter=1;this.deploy(['synth','seer','brute','stalker','synth','seer','synth'],[{x:-18,z:-17},{x:18,z:-17},{x:0,z:-23}]);}
 else if(this.stage==='reactor'&&this.stabilizers.every(Boolean)&&!this.enemies.length){this.setStage('extraction');this.extractionStarted=this.time;this.activePortals=[{id:777,...BREACH.exit,yaw:0,openedAt:this.time}];}
 for(const [i,s] of [{x:-23,z:30},{x:23,z:-64}].entries())if(!this.secretFound[i]&&Math.hypot(p.x-s.x,p.z-s.z)<2.4){this.secretFound[i]=true;this.player.hp=100;this.score+=500;this.offerWeapon(i+2);this.event('campaign',{title:'CACHE DÉCOUVERTE',subtitle:'Énergie restaurée · Arme disponible'});}
 }
 objectiveTarget(){const o=this.campaign.objective;if(o)return {...o.position,id:o.id,label:o.label,kind:'objective'};const enemy=this.enemies[0];if(enemy)return {x:enemy.x,z:enemy.z,y:enemy.homeHeight||0,id:`enemy-${enemy.id}`,label:'NEUTRALISER LES HOSTILES',kind:'enemy'};return {x:0,y:0,z:this.stage==='arrival'?59:-3,id:'route',label:'SUIVRE LA LIGNE BLEUE',kind:'route'};}
 guidance(){const t=this.objectiveTarget();return t?{...t,distance:Math.hypot(t.x-this.player.x,t.z-this.player.z),target:t,stage:this.stage}:null;}
}
